// ParseOpaStateServiceRpcIds converts a comma-separated string to a slice of OpaStateServiceRpcId enum values
// Returns an error if any value is invalid
func ParseOpaStateServiceRpcIds(s string) ([]OpaStateServiceRpcId, error) {
	if s == "" {
		return nil, nil
	}
	parts := strings.Split(s, ",")
	result := make([]OpaStateServiceRpcId, 0, len(parts))
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed == "" {
			continue
		}
		val, err := ParseOpaStateServiceRpcId(trimmed)
		if err != nil {
			return nil, err
		}
		result = append(result, val)
	}
	return result, nil
}

